def post_local_orders_hold_once(reason: str) -> int:
    """Return the 2xx HTTP status after posting exactly one concise HOLD notification with the required one-key JSON shape. Follow the linked guidance “Fail-closed scheduled HTTP batch aggregation and delivery”."""
    import json
    import logging
    import urllib.request

    if type(reason) is not str:
        raise TypeError("reason must be a string")
    concise = " ".join(reason.split()) or "unspecified processing failure"
    if len(concise) > 320:
        concise = concise[:317] + "..."
    payload = {"message": "HOLD: " + concise}
    body = json.dumps(
        payload,
        ensure_ascii=True,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("utf-8")

    class NoRedirectHTTPErrorProcessor(urllib.request.HTTPErrorProcessor):
        def http_response(self, request, response):
            return response
        https_response = http_response

    logging.getLogger(__name__).info("PHASE owner_hold_notification")
    request = urllib.request.Request(
        url="http://127.0.0.1:18181/owner/notify",
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    opener = urllib.request.build_opener(NoRedirectHTTPErrorProcessor())
    try:
        with opener.open(request, timeout=5.0) as response:
            status = response.getcode()
    except Exception as exc:
        raise RuntimeError(
            f"owner HOLD notification POST failed: {type(exc).__name__}: {exc}"
        ) from exc
    if type(status) is not int or not 200 <= status <= 299:
        raise RuntimeError(
            f"owner HOLD notification POST returned non-2xx status {status!r}"
        )
    return status

