def verify_local_orders_batch(prepared: dict[str, object]) -> dict[str, object]:
    """Return the exact six-key batch payload only if independently revalidating and recomputing the prepared orders reproduces it. Follow the linked guidance “Fail-closed scheduled HTTP batch aggregation and delivery”."""
    import datetime
    import json
    import logging
    import re

    log = logging.getLogger(__name__)
    log.info("PHASE independent_revalidation")
    expected_prepared_keys = {"status", "last_seq", "orders", "payload"}
    order_keys = {"seq", "date", "region", "units", "amount"}
    payload_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_amount_minor",
        "amount_by_region_minor",
    }
    date_re = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    if type(prepared) is not dict or set(prepared) != expected_prepared_keys:
        raise ValueError("prepared result has unexpected keys")
    if prepared["status"] != "prepared":
        raise ValueError("prepared result status is not 'prepared'")
    last_seq = prepared["last_seq"]
    orders = prepared["orders"]
    candidate = prepared["payload"]
    if type(last_seq) is not int or last_seq < 0:
        raise ValueError("prepared last_seq is not a nonnegative integer")
    if type(orders) is not list or not orders or len(orders) > 100:
        raise ValueError("prepared orders must be a nonempty list of at most 100")
    if type(candidate) is not dict or set(candidate) != payload_keys:
        raise ValueError("candidate batch payload has unexpected keys")

    previous = last_seq
    seen = set()
    checked = []
    for index, order in enumerate(orders):
        if type(order) is not dict or set(order) != order_keys:
            raise ValueError(f"prepared order index {index} has unexpected keys")
        for field in ("seq", "units", "amount"):
            if type(order[field]) is not int:
                raise ValueError(
                    f"prepared order index {index} field {field!r} is not an integer"
                )
        seq = order["seq"]
        if seq <= last_seq or seq <= previous or seq in seen:
            raise ValueError(f"prepared sequence invariant failed at index {index}")
        date_text = order["date"]
        if type(date_text) is not str or date_re.fullmatch(date_text) is None:
            raise ValueError(f"prepared date invariant failed at index {index}")
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError as exc:
            raise ValueError(f"prepared date is not real at index {index}") from exc
        if type(order["region"]) is not str:
            raise ValueError(f"prepared region is not a string at index {index}")
        previous = seq
        seen.add(seq)
        checked.append(order)

    for field in (
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_amount_minor",
    ):
        if type(candidate[field]) is not int:
            raise ValueError(f"candidate payload field {field!r} is not an integer")
    grouped_candidate = candidate["amount_by_region_minor"]
    if type(grouped_candidate) is not dict:
        raise ValueError("candidate amount_by_region_minor is not an object")
    if any(type(k) is not str or type(v) is not int for k, v in grouped_candidate.items()):
        raise ValueError("candidate regional amounts have invalid key/value types")

    grouped_check = {}
    for order in reversed(checked):
        region = order["region"]
        grouped_check[region] = order["amount"] + grouped_check.get(region, 0)
    recomputed = {
        "batch_start_seq": checked[0]["seq"],
        "batch_end_seq": checked[len(checked) - 1]["seq"],
        "order_count": sum(1 for _ in checked),
        "total_units": sum(order["units"] for order in checked),
        "total_amount_minor": sum(order["amount"] for order in checked),
        "amount_by_region_minor": grouped_check,
    }
    if candidate != recomputed:
        raise ValueError("candidate batch payload failed independent recomputation")
    json.dumps(recomputed, ensure_ascii=True, allow_nan=False, separators=(",", ":"))
    return recomputed

