def prepare_local_orders_batch() -> dict[str, object]:
    """Return either a validated empty-batch result or validated orders plus a candidate payload from the fixed local API. Follow the linked guidance “Fail-closed scheduled HTTP batch aggregation and delivery”."""
    import datetime
    import json
    import logging
    import re
    import urllib.parse
    import urllib.request

    log = logging.getLogger(__name__)
    base = "http://127.0.0.1:18181"
    timeout_s = 5.0
    order_keys = {"seq", "date", "region", "units", "amount"}
    date_re = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    class ValidationError(Exception):
        pass

    class NoRedirectHTTPErrorProcessor(urllib.request.HTTPErrorProcessor):
        def http_response(self, request, response):
            return response
        https_response = http_response

    def strict_object(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise ValidationError(f"duplicate JSON object key {key!r}")
            obj[key] = value
        return obj

    def reject_nonfinite(token):
        raise ValidationError(f"non-finite JSON number {token!r}")

    def get_json(url, label):
        opener = urllib.request.build_opener(NoRedirectHTTPErrorProcessor())
        request = urllib.request.Request(url=url, method="GET")
        try:
            with opener.open(request, timeout=timeout_s) as response:
                status = response.getcode()
                body = response.read()
        except Exception as exc:
            raise RuntimeError(f"{label} GET failed: {type(exc).__name__}: {exc}") from exc
        if type(status) is not int or not 200 <= status <= 299:
            raise RuntimeError(f"{label} GET returned non-2xx status {status!r}")
        try:
            text = body.decode("utf-8", errors="strict")
        except UnicodeDecodeError as exc:
            raise ValidationError(f"{label} body is not valid UTF-8: {exc}") from exc
        try:
            return json.loads(
                text,
                object_pairs_hook=strict_object,
                parse_constant=reject_nonfinite,
            )
        except (json.JSONDecodeError, ValidationError) as exc:
            raise ValidationError(
                f"{label} body is not valid unambiguous JSON: {exc}"
            ) from exc

    log.info("PHASE fetch_last_seq")
    last_raw = get_json(base + "/batches/last", "batches/last")
    if type(last_raw) is not dict or set(last_raw) != {"last_seq"}:
        raise ValidationError(
            "batches/last JSON must be an object with exactly key 'last_seq'"
        )
    last_seq = last_raw["last_seq"]
    if type(last_seq) is not int:
        raise ValidationError("last_seq must be a JSON integer and not a boolean")
    if last_seq < 0:
        raise ValidationError(f"last_seq must be >= 0, observed {last_seq}")

    log.info("PHASE fetch_orders after=%d", last_seq)
    query = urllib.parse.urlencode({"after": last_seq})
    orders_raw = get_json(base + "/orders?" + query, "orders")
    if type(orders_raw) is not list:
        raise ValidationError("orders JSON must be an array")
    if len(orders_raw) > 100:
        raise ValidationError(
            f"orders array exceeds 100 elements: observed {len(orders_raw)}"
        )

    orders = []
    previous = last_seq
    seen = set()
    for index, order in enumerate(orders_raw):
        if type(order) is not dict or set(order) != order_keys:
            raise ValidationError(
                f"order index {index} must have exactly keys {sorted(order_keys)}"
            )
        for field in ("seq", "units", "amount"):
            if type(order[field]) is not int:
                raise ValidationError(
                    f"order index {index} field {field!r} must be a JSON integer and not a boolean"
                )
        seq = order["seq"]
        if seq <= last_seq:
            raise ValidationError(
                f"order index {index} seq {seq} is not greater than last_seq {last_seq}"
            )
        if seq <= previous:
            raise ValidationError(
                f"orders are not strictly ascending at index {index}: {seq} after {previous}"
            )
        if seq in seen:
            raise ValidationError(f"duplicate seq {seq} at order index {index}")
        date_text = order["date"]
        if type(date_text) is not str or date_re.fullmatch(date_text) is None:
            raise ValidationError(
                f"order index {index} date must be an exact YYYY-MM-DD string"
            )
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError as exc:
            raise ValidationError(
                f"order index {index} date is not real: {date_text!r}"
            ) from exc
        if type(order["region"]) is not str:
            raise ValidationError(f"order index {index} region must be a JSON string")
        previous = seq
        seen.add(seq)
        orders.append(dict(order))

    if not orders:
        log.info("SKIP empty_batch last_seq=%d", last_seq)
        return {"status": "no_op", "reason": "empty_batch", "last_seq": last_seq}

    log.info("PHASE compute_candidate order_count=%d", len(orders))
    total_units = 0
    total_amount = 0
    by_region = {}
    for order in orders:
        total_units += order["units"]
        total_amount += order["amount"]
        region = order["region"]
        by_region[region] = by_region.get(region, 0) + order["amount"]
    payload = {
        "batch_start_seq": orders[0]["seq"],
        "batch_end_seq": orders[-1]["seq"],
        "order_count": len(orders),
        "total_units": total_units,
        "total_amount_minor": total_amount,
        "amount_by_region_minor": by_region,
    }
    return {
        "status": "prepared",
        "last_seq": last_seq,
        "orders": orders,
        "payload": payload,
    }
